 const capture=(force=false)=>{if(!owned()||(!force&&!current()))return;for(const detail of root.querySelectorAll('[data-rsb-detail]'))state.open[detail.dataset.rsbDetail]=typeof detail.open==='boolean'?detail.open:detail.getAttribute('open')!==null;};
 root.innerHTML='<section class="rsb-panel"><h3>从复振幅到密度矩阵</h3><p>基底顺序固定为 ↑、↓，初态为 ↑。下方显示所选时间点的 Python 复态和演化矩阵；外积账本逐项核对它们。沿上方轨迹滑块换时间，不会重新求解动力学。</p><button type="button" class="secondary" id="rsb-mid">查看中间时间采样点</button><div id="rsb-ledger"></div><button type="button" class="secondary" id="rsb-step">展开下一步外积推导</button><details data-rsb-detail="phase"><summary>改变条件：整体相位与相对相位</summary><p>这是对当前复态施加相位的有限对照，不是重新运行原来的哈密顿量。</p><div class="rsb-controls">'+select('rsb-phase-kind','施加在哪些分量上',[['global','两个分量同时变化'],['relative','只改变 ↓ 分量']],state.kind)+select('rsb-phase','相位 φ',[[0,'0'],[1,'π/2'],[2,'π'],[3,'3π/2']],state.phase)+'</div><div id="rsb-phase-result"></div></details><details data-rsb-detail="questions"><summary>先预测，再核对两道判断</summary>'+questions.map((q,i)=>'<p>'+esc(q.prompt)+'</p>'+select('rsb-q'+i,'选择预测',q.options,state.choices[i])+'<button type="button" class="secondary" id="rsb-check'+i+'">核对本题</button><p id="rsb-feedback'+i+'" class="rsb-feedback" role="status"></p>').join('')+'</details><label class="rsb-note">写下自己的解释（仅保留在本次结果的页面内存）<textarea id="rsb-note" rows="2" maxlength="2000">'+esc(state.note)+'</textarea></label><a href="#classroom/spin?module=density&lesson=density-lindblad&tab=learn">继续学习密度矩阵与退相干 →</a></section>';
 panel=root.querySelector('.rsb-panel');
 const restoreDetails=()=>{for(const detail of root.querySelectorAll('[data-rsb-detail]')){if(state.open[detail.dataset.rsbDetail]){detail.open=true;detail.setAttribute('open','');}detail.ontoggle=()=>{if(current()&&root.querySelector('[data-rsb-detail="'+detail.dataset.rsbDetail+'"]')===detail){capture();save();}};}};
 const paintPhase=ledger=>{if(!ledger){$('#rsb-phase-result').innerHTML='';return;}const view=rabiPhaseComparison(ledger.state,{kind:state.kind,quarterTurns:state.phase});$('#rsb-phase-result').innerHTML=table('相位对照的振幅与概率',['分量','新振幅','新概率'],[['↑',complex(view.state[0]),num(view.probabilities[0])],['↓',complex(view.state[1]),num(view.probabilities[1])]])+matrixHTML(view.rho)+'<p data-math-ignore>max |Δρ| = '+num(view.densityChange)+'; Bloch = ('+view.bloch.map(num).join(', ')+')</p>'+(state.kind==='global'?'<p>整体相位在外积中相消；矩阵和可观测概率保持不变。</p>':view.coherenceMagnitude<1e-12?'<p>当前几乎只有一个非零分量，相对相位不能由这份 ρ 区分。请选择含两个分量的采样点再比较。</p>':'<p>两个布居概率分别保持原值；非对角相干项和横向 Bloch 分量可以改变，布居不能确定全部量子态。</p>');};
 function paint(){if(!current())return;capture();let ledger;try{ledger=rabiStateLedger(result,state.index);$('#rsb-ledger').innerHTML=ledgerHTML(ledger,state.step);paintPhase(ledger);$('#rsb-step').disabled=!ledger;$('#rsb-step').textContent=state.step>=3?'收起外积推导':'展开下一步外积推导';restoreDetails();save();}catch(error){$('#rsb-ledger').innerHTML='<p role="alert">'+esc(error.message)+'</p>';$('#rsb-step').disabled=true;}}
 const bind=(id,event,handler)=>{const node=$(id);node[event]=()=>{if(!current()||$(id)!==node)return;capture();handler(node);save();};};
